code.C:
#include <stdio.h>
#include <string.h>
int main() {
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    int len = strlen(s);
    for (int i = len - 1; i >= 0; i--) {
        printf("%c", s[i]);
        if (i > 0) printf(" ");
    }
    printf("\n");
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    string s; if (!(cin >> s)) return 0;
    for (int i = (int)s.length() - 1; i >= 0; i--) {
        cout << s[i];
        if (i > 0) cout << " ";
    }
    cout << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            StringBuilder sb = new StringBuilder();
            for (int i = s.length() - 1; i >= 0; i--) {
                sb.append(s.charAt(i));
                if (i > 0) sb.append(" ");
            }
            System.out.println(sb.toString());
        }
    }
}

